preConditionHook:
// THE 3/10 OSCILLATOR -- Grimes's fast line, in the settled form (merge
// decision 2): the difference of two SIMPLE averages of the close,
//     osc = average of close over fastLen bars, less the average
//           of close over slowLen bars
// with fastLen 3 and slowLen 10 as the book's defaults. Never the MACD word:
// Appendix B spells the construction out as plain moving averages, and the
// chapter 16 restatement in exponential terms loses to it.
// EL's Average RECOMPUTES from scratch every bar (VERIFIED: matched a fresh
// loop on 2,808/2,808 bars; it is NOT a rolling accumulator like the WFSafe_
// wrappers), and Summation adds the newest bar first and works backwards,
// with a single divide at the end -- which is how the loops below run.
// Both averages run over a PRICE expression, which has real bar history, so
// they are recomputed from the bars rather than mirrored; only osc ITSELF is
// a variable, and that is what the ring buffers below mirror.
// The whole quantity is a difference of prices, so it passes the shift test.
// Scratch is declared in localVariables, never at hook scope: the generator
// only prefixes declared locals, so a hook-scope declaration is a
// redefinition when the rule is placed twice in one strategy.
oscFast = 0.0;
for (int i = 0; i < (int)fastLen; ++i) {
    oscFast += close[i];
}
oscFast = oscFast / (int)fastLen;
oscSlow = 0.0;
for (int i = 0; i < (int)slowLen; ++i) {
    oscSlow += close[i];
}
oscSlow = oscSlow / (int)slowLen;
osc = oscFast - oscSlow;
// A NEW OSCILLATOR EXTREME: the fast line is at or above the highest value it
// reached over the oscLookback bars ENDING ONE BAR AGO (short: the lowest).
// osc is an EL VARIABLE, so osc[k] reads the variable's OWN history, which
// holds its initial 0 for every bar before the strategy's first evaluated
// one. Mirrored here as a zero-seeded ring buffer, re-seeded if the depth
// ever changes -- exactly what AwesomeOscillatorSlope, AtrRising and
// BarRangeAboveStd do for the same reason. The rule GUARDS its own warm-up
// on the bar counter instead of comparing against those zeros.
// Depth oscLookback + 1 so lag 0 and lag oscLookback both live in the buffer.
oscDepth = (int)oscLookback + 1;
if (oscDepth < 2) {
    oscDepth = 2;
}
if (oscHistory.size() != (std::size_t)oscDepth) {
    oscHistory.assign((std::size_t)oscDepth, 0.0);
    oscCursor = 0;
}
oscHistory[oscCursor] = osc;
oscCursor = (oscCursor + 1) % oscHistory.size();
// The window extreme, mirroring EasyLanguage's Extremes(): seed on the
// window's first bar -- here osc[1], the one-bar shift -- and scan the rest
// with a STRICT comparison, so a tie keeps the seed. Extremes is EL SOURCE,
// so its comparison carries the EL relational tolerance: el_gt / el_lt, as
// Breakout and TightRangeBlocksEntries do.
oscPeak = oscHistory[(oscCursor + oscHistory.size() - 2) % oscHistory.size()];
oscTrough = oscPeak;
for (ii = 2; ii <= (int)oscLookback; ++ii) {
    double v = oscHistory[(oscCursor + oscHistory.size() - 1 - (std::size_t)ii) % oscHistory.size()];
    if (el_gt(v, oscPeak)) {
        oscPeak = v;
    }
    if (el_lt(v, oscTrough)) {
        oscTrough = v;
    }
}
// Warm-up: against the zero-filled osc history the long side would pass
// trivially for the first oscLookback bars, so the rule waits until every
// bar of the window is a real reading rather than comparing against a zero.
oscReady = ctx.CurrentBar() > (int)oscLookback;
